{
  "title": "Why the Pythagorean Theorem Works",
  "lang": "en",
  "steps": [
    {
      "title": "The claim",
      "say": "The Pythagorean theorem says that for a right triangle, a² + b² = c².",
      "ops": [
        { "id": "title", "op": "write", "x": 800, "y": 60, "text": "Why a² + b² = c²?", "size": 56, "anchor": "middle" },
        { "id": "eq", "op": "write", "x": 800, "y": 150, "text": "a² + b² = c²", "size": 48, "anchor": "middle", "color": "blue" }
      ]
    },
    {
      "title": "Draw the triangle",
      "say": "Start with a right triangle with legs a and b and hypotenuse c.",
      "ops": [
        { "id": "tri", "op": "path", "d": "M 300 700 L 300 400 L 700 700 Z", "color": "ink", "width": 5 },
        { "id": "right_angle", "op": "path", "d": "M 300 660 L 340 660 L 340 700", "color": "gray", "width": 3 },
        { "id": "lbl_a", "op": "write", "x": 270, "y": 540, "text": "a", "size": 40, "anchor": "middle" },
        { "id": "lbl_b", "op": "write", "x": 500, "y": 720, "text": "b", "size": 40, "anchor": "middle" },
        { "id": "lbl_c", "op": "write", "x": 520, "y": 520, "text": "c", "size": 40, "anchor": "middle" }
      ]
    },
    {
      "title": "Build the big square",
      "say": "Put four copies of the triangle inside a square of side a + b.",
      "ops": [
        { "id": "big_sq", "op": "rect", "x": 900, "y": 300, "w": 400, "h": 400, "color": "ink", "width": 4 },
        { "id": "t1", "op": "path", "d": "M 900 300 L 1100 300 L 900 500 Z", "color": "blue", "width": 3 },
        { "id": "t2", "op": "path", "d": "M 1300 300 L 1300 500 L 1100 300 Z", "color": "blue", "width": 3 },
        { "id": "t3", "op": "path", "d": "M 1300 700 L 1100 700 L 1300 500 Z", "color": "blue", "width": 3 },
        { "id": "t4", "op": "path", "d": "M 900 700 L 900 500 L 1100 700 Z", "color": "blue", "width": 3 },
        { "id": "inner_sq", "op": "rect", "x": 1100, "y": 500, "w": 200, "h": 200, "color": "red", "width": 4, "fill": "red" }
      ]
    },
    {
      "title": "Area bookkeeping",
      "say": "The big square has area (a+b)². It is made of four triangles plus the tilted inner square of area c².",
      "ops": [
        { "id": "area_eq", "op": "write", "x": 800, "y": 760, "text": "(a+b)² = 4·(½ab) + c²", "size": 40, "anchor": "middle", "color": "ink" },
        { "id": "expand", "op": "write", "x": 800, "y": 820, "text": "a² + 2ab + b² = 2ab + c²", "size": 40, "anchor": "middle", "color": "ink" }
      ]
    },
    {
      "title": "Cancel to finish",
      "say": "Cancel 2ab from both sides and you are left with a² + b² = c².",
      "ops": [
        { "id": "cancel", "op": "write", "x": 800, "y": 860, "text": "a² + b² = c²", "size": 44, "anchor": "middle", "color": "green" }
      ]
    }
  ]
}

{
  "title": "Why the Pythagorean Theorem Works",
  "lang": "en",
  "steps": [
    {
      "title": "The theorem",
      "say": "For a right triangle with legs a and b and hypotenuse c, a squared plus b squared equals c squared.",
      "ops": [
        { "id": "title", "x": 800, "y": 50, "text": "Why does a² + b² = c² ?", "size": 54, "anchor": "middle" },
        { "id": "eq", "x": 800, "y": 140, "text": "a² + b² = c²", "size": 48, "anchor": "middle", "color": "blue" }
      ]
    },
    {
      "title": "Draw the triangle",
      "say": "Start with a right triangle. The two shorter sides are a and b, and the longest side is c.",
      "ops": [
        { "id": "tri", "d": "M 300 700 L 300 450 L 600 700 Z", "color": "ink", "width": 6 },
        { "id": "right", "d": "M 300 670 L 330 670 L 330 700", "color": "gray", "width": 4 },
        { "id": "lbl_a", "x": 265, "y": 560, "text": "a", "size": 44, "color": "red", "anchor": "middle" },
        { "id": "lbl_b", "x": 450, "y": 720, "text": "b", "size": 44, "color": "green", "anchor": "middle" },
        { "id": "lbl_c", "x": 470, "y": 555, "text": "c", "size": 44, "color": "blue", "anchor": "middle" }
      ]
    },
    {
      "title": "Build squares on the legs",
      "say": "Build a square on each leg. The red square has area a squared, and the green square has area b squared.",
      "ops": [
        { "id": "sq_a", "x": 120, "y": 450, "w": 180, "h": 250, "color": "red", "width": 4, "fill": "red" },
        { "id": "sq_b", "x": 300, "y": 700, "w": 300, "h": 180, "color": "green", "width": 4, "fill": "green" },
        { "id": "area_a", "x": 210, "y": 560, "text": "a²", "size": 40, "color": "red", "anchor": "middle" },
        { "id": "area_b", "x": 450, "y": 790, "text": "b²", "size": 40, "color": "green", "anchor": "middle" }
      ]
    },
    {
      "title": "Build the square on the hypotenuse",
      "say": "The square on the hypotenuse has area c squared. We want to show the two small squares together fill exactly this big square.",
      "ops": [
        { "id": "sq_c", "d": "M 600 700 L 900 700 L 1050 450 L 750 450 Z", "color": "blue", "width": 4, "fill": "blue" },
        { "id": "area_c", "x": 825, "y": 575, "text": "c²", "size": 44, "color": "blue", "anchor": "middle" }
      ]
    },
    {
      "title": "Rearrange the pieces",
      "say": "Cut the two small squares into pieces and slide them into the big square. They fit perfectly, with no gaps or overlaps.",
      "ops": [
        { "id": "cut1", "x1": 210, "y1": 450, "x2": 210, "y2": 700, "color": "gray", "width": 3, "dash": true },
        { "id": "cut2", "x1": 120, "y1": 575, "x2": 300, "y2": 575, "color": "gray", "width": 3, "dash": true },
        { "id": "cut3", "x1": 450, "y1": 700, "x2": 450, "y2": 880, "color": "gray", "width": 3, "dash": true },
