    {
      "title": "Winter: low Sun, short days",
      "say": "In northern winter, the northern half is tilted away from the Sun. The Sun stays low and daylight is short, so it stays cold.",
      "ops": [
        {
          "op": "write",
          "id": "winter-why",
          "x": 60,
          "y": 1110,
          "text": "Northern winter: low Sun + short daylight = less heat.",
