        { "id": "shiftlabel", "op": "write", "x": 870, "y": 640, "text": "shift", "size": 30, "color": "blue" }
      ]
    },
    {
      "title": "New equilibrium: higher price",
      "say": "The new intersection is higher up: price rises to P2, and quantity rises to Q2.",
      "ops": [
        { "id": "eqdot2", "op": "ellipse", "cx": 820, "cy": 360, "rx": 10, "ry": 10, "fill": "red" },
        { "id": "p2line", "op": "line", "x1": 220, "y1": 360, "x2": 820, "y2": 360, "width": 3, "dash": true, "color": "red" },
        { "id": "p2label", "op": "write", "x": 150, "y": 330, "text": "P2", "size": 34, "color": "red" },
        { "id": "q2line", "op": "line", "x1": 820, "y1": 360, "x2": 820, "y2": 760, "width": 3, "dash": true, "color": "red" },
        { "id": "q2label", "op": "write", "x": 790, "y": 770, "text": "Q2", "size": 34, "color": "red" },
        { "id": "uparrow", "op": "line", "x1": 250, "y1": 470, "x2": 250, "y2": 360, "width": 5, "color": "red", "arrow": true },
        { "id": "pricerise", "op": "write", "x": 270, "y": 400, "text": "price ↑", "size": 34, "color": "red" }
      ]
    }
  ]
}

